class Solution:
    def canMakePalindromeQueries(self, s: str, queries: list[list[int]]) -> list[bool]:
        n = len(s)
        m = n // 2
        s1 = s[:m]
        s2 = s[m:][::-1]
        diff = [0] * (m + 1)
        for i in range(m):
            diff[i + 1] = diff[i] + (1 if s1[i] != s2[i] else 0)
        cnt1 = [[0] * 26 for _ in range(m + 1)]
        cnt2 = [[0] * 26 for _ in range(m + 1)]
        for i in range(m):
            for c in range(26):
                cnt1[i + 1][c] = cnt1[i][c]
                cnt2[i + 1][c] = cnt2[i][c]
            cnt1[i + 1][ord(s1[i]) - 97] += 1
            cnt2[i + 1][ord(s2[i]) - 97] += 1

        def get_cnt(pref, l, r):
            if l > r:
                return [0] * 26
            return [pref[r + 1][c] - pref[l][c] for c in range(26)]

        ans = []
        for a, b, c, d in queries:
            c_prime = n - 1 - d
            d_prime = n - 1 - c
            l1, r1 = a, b
            l2, r2 = c_prime, d_prime
            min_l = min(l1, l2)
            max_r = max(r1, r2)
            if diff[min_l] > 0 or (diff[m] - diff[max_r + 1]) > 0:
                ans.append(False)
                continue
            if max(l1, l2) > min(r1, r2) + 1:
                mid_l = min(r1, r2) + 1
                mid_r = max(l1, l2) - 1
                if diff[mid_r + 1] - diff[mid_l] > 0:
                    ans.append(False)
                    continue
            c1 = get_cnt(cnt1, l1, r1)
            c2 = get_cnt(cnt2, l2, r2)
            if r1 < l2 or r2 < l1:
                ok1 = (c1 == get_cnt(cnt2, l1, r1))
                ok2 = (c2 == get_cnt(cnt1, l2, r2))
                ans.append(ok1 and ok2)
            else:
                inter_l = max(l1, l2)
                inter_r = min(r1, r2)
                ok = True
                rem1 = [c1[k] for k in range(26)]
                rem2 = [c2[k] for k in range(26)]
                if l1 < inter_l:
                    sub = get_cnt(cnt2, l1, inter_l - 1)
                    for k in range(26):
                        rem1[k] -= sub[k]
                        if rem1[k] < 0: ok = False
                elif l2 < inter_l:
                    sub = get_cnt(cnt1, l2, inter_l - 1)
                    for k in range(26):
                        rem2[k] -= sub[k]
                        if rem2[k] < 0: ok = False
                if r1 > inter_r:
                    sub = get_cnt(cnt2, inter_r + 1, r1)
                    for k in range(26):
                        rem1[k] -= sub[k]
                        if rem1[k] < 0: ok = False
                elif r2 > inter_r:
                    sub = get_cnt(cnt1, inter_r + 1, r2)
                    for k in range(26):
                        rem2[k] -= sub[k]
                        if rem2[k] < 0: ok = False
                if not ok or rem1 != rem2:
                    ans.append(False)
                else:
                    ans.append(True)
        return ans

#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<bool> canMakePalindromeQueries(std::string s, std::vector<std::vector<int>>& queries) {
        int n = s.size();
        int m = n / 2;
        std::string s1 = s.substr(0, m);
        std::string s2 = s.substr(m);
        std::reverse(s2.begin(), s2.end());

        std::vector<int> diff(m + 1, 0);
        for (int i = 0; i < m; ++i) {
            diff[i + 1] = diff[i] + (s1[i] != s2[i]);
        }
        std::vector<std::vector<int>> cnt1(m + 1, std::vector<int>(26, 0));
        std::vector<std::vector<int>> cnt2(m + 1, std::vector<int>(26, 0));
        for (int i = 0; i < m; ++i) {
            for (int c = 0; c < 26; ++c) {
                cnt1[i + 1][c] = cnt1[i][c];
                cnt2[i + 1][c] = cnt2[i][c];
            }
            cnt1[i + 1][s1[i] - 'a']++;
            cnt2[i + 1][s2[i] - 'a']++;
        }

        auto getCnt = [&](const std::vector<std::vector<int>>& pref, int l, int r) {
            std::vector<int> res(26, 0);
            if (l <= r) {
                for (int c = 0; c < 26; ++c) res[c] = pref[r + 1][c] - pref[l][c];
            }
            return res;
        };

        std::vector<bool> ans;
        for (const auto& q : queries) {
            int a = q[0], b = q[1];
            int c = n - 1 - q[3], d = n - 1 - q[2];
            int minL = std::min(a, c);
            int maxR = std::max(b, d);
            if (diff[minL] > 0 || (diff[m] - diff[maxR + 1]) > 0) {
                ans.push_back(false);
                continue;
            }
            if (std::max(a, c) > std::min(b, d) + 1) {
                int midL = std::min(b, d) + 1;
                int midR = std::max(a, c) - 1;
                if (diff[midR + 1] - diff[midL] > 0) {
                    ans.push_back(false);
                    continue;
                }
            }
            auto c1 = getCnt(cnt1, a, b);
            auto c2 = getCnt(cnt2, c, d);
            if (b < c || d < a) {
                bool ok1 = (c1 == getCnt(cnt2, a, b));
                bool ok2 = (c2 == getCnt(cnt1, c, d));
                ans.push_back(ok1 && ok2);
            } else {
                int interL = std::max(a, c);
                int interR = std::min(b, d);
                bool ok = true;
                auto rem1 = c1;
                auto rem2 = c2;
                if (a < interL) {
                    auto sub = getCnt(cnt2, a, interL - 1);
                    for (int k = 0; k < 26; ++k) {
                        rem1[k] -= sub[k];
                        if (rem1[k] < 0) ok = false;
                    }
                } else if (c < interL) {
                    auto sub = getCnt(cnt1, c, interL - 1);
                    for (int k = 0; k < 26; ++k) {
                        rem2[k] -= sub[k];
                        if (rem2[k] < 0) ok = false;
                    }
                }
                if (b > interR) {
                    auto sub = getCnt(cnt2, interR + 1, b);
                    for (int k = 0; k < 26; ++k) {
                        rem1[k] -= sub[k];
                        if (rem1[k] < 0) ok = false;
                    }
                } else if (d > interR) {
                    auto sub = getCnt(cnt1, interR + 1, d);
                    for (int k = 0; k < 26; ++k) {
                        rem2[k] -= sub[k];
                        if (rem2[k] < 0) ok = false;
                    }
                }
                if (!ok || rem1 != rem2) {
                    ans.push_back(false);
                } else {
                    ans.push_back(true);
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public boolean[] canMakePalindromeQueries(String s, int[][] queries) {
        int n = s.length();
        int m = n / 2;
        char[] s1 = s.substring(0, m).toCharArray();
        char[] s2 = new StringBuilder(s.substring(m)).reverse().toString().toCharArray();

        int[] diff = new int[m + 1];
        for (int i = 0; i < m; i++) {
            diff[i + 1] = diff[i] + (s1[i] != s2[i] ? 1 : 0);
        }

        int[][] cnt1 = new int[m + 1][26];
        int[][] cnt2 = new int[m + 1][26];
        for (int i = 0; i < m; i++) {
            System.arraycopy(cnt1[i], 0, cnt1[i + 1], 0, 26);
            System.arraycopy(cnt2[i], 0, cnt2[i + 1], 0, 26);
            cnt1[i + 1][s1[i] - 'a']++;
            cnt2[i + 1][s2[i] - 'a']++;
        }

        boolean[] ans = new boolean[queries.length];
        for (int qIdx = 0; qIdx < queries.length; qIdx++) {
            int a = queries[qIdx][0], b = queries[qIdx][1];
            int c = n - 1 - queries[qIdx][3], d = n - 1 - queries[qIdx][2];
            int minL = Math.min(a, c);
            int maxR = Math.max(b, d);

            if (diff[minL] > 0 || (diff[m] - diff[maxR + 1]) > 0) {
                ans[qIdx] = false;
                continue;
            }
            if (Math.max(a, c) > Math.min(b, d) + 1) {
                int midL = Math.min(b, d) + 1;
                int midR = Math.max(a, c) - 1;
                if (diff[midR + 1] - diff[midL] > 0) {
                    ans[qIdx] = false;
                    continue;
                }
            }

            int[] c1 = getCnt(cnt1, a, b);
            int[] c2 = getCnt(cnt2, c, d);
            if (b < c || d < a) {
                boolean ok1 = Arrays.equals(c1, getCnt(cnt2, a, b));
                boolean ok2 = Arrays.equals(c2, getCnt(cnt1, c, d));
                ans[qIdx] = ok1 && ok2;
            } else {
                int interL = Math.max(a, c);
                int interR = Math.min(b, d);
                boolean ok = true;
                int[] rem1 = c1.clone();
                int[] rem2 = c2.clone();
                if (a < interL) {
                    int[] sub = getCnt(cnt2, a, interL - 1);
                    for (int k = 0; k < 26; k++) {
                        rem1[k] -= sub[k];
                        if (rem1[k] < 0) ok = false;
                    }
                } else if (c < interL) {
                    int[] sub = getCnt(cnt1, c, interL - 1);
                    for (int k = 0; k < 26; k++) {
                        rem2[k] -= sub[k];
                        if (rem2[k] < 0) ok = false;
                    }
                }
                if (b > interR) {
                    int[] sub = getCnt(cnt2, interR + 1, b);
                    for (int k = 0; k < 26; k++) {
                        rem1[k] -= sub[k];
                        if (rem1[k] < 0) ok = false;
                    }
                } else if (d > interR) {
                    int[] sub = getCnt(cnt1, interR + 1, d);
                    for (int k = 0; k < 26; k++) {
                        rem2[k] -= sub[k];
                        if (rem2[k] < 0) ok = false;
                    }
                }
                if (!ok || !Arrays.equals(rem1, rem2)) {
                    ans[qIdx] = false;
                } else {
                    ans[qIdx] = true;
                }
            }
        }
        return ans;
    }

    private int[] getCnt(int[][] pref, int l, int r) {
        int[] res = new int[26];
        if (l <= r) {
            for (int c = 0; c < 26; c++) res[c] = pref[r + 1][c] - pref[l][c];
        }
        return res;
    }
}

var canMakePalindromeQueries = function(s, queries) {
    const n = s.length;
    const m = Math.floor(n / 2);
    const s1 = s.slice(0, m);
    const s2 = s.slice(m).split('').reverse().join('');

    const diff = new Array(m + 1).fill(0);
    for (let i = 0; i < m; i++) {
        diff[i + 1] = diff[i] + (s1[i] !== s2[i] ? 1 : 0);
    }
    const cnt1 = Array.from({ length: m + 1 }, () => new Array(26).fill(0));
    const cnt2 = Array.from({ length: m + 1 }, () => new Array(26).fill(0));
    for (let i = 0; i < m; i++) {
        for (let c = 0; c < 26; c++) {
            cnt1[i + 1][c] = cnt1[i][c];
            cnt2[i + 1][c] = cnt2[i][c];
        }
        cnt1[i + 1][s1.charCodeAt(i) - 97]++;
        cnt2[i + 1][s2.charCodeAt(i) - 97]++;
    }

    function getCnt(pref, l, r) {
        const res = new Array(26).fill(0);
        if (l <= r) {
            for (let c = 0; c < 26; c++) res[c] = pref[r + 1][c] - pref[l][c];
        }
        return res;
    }

    const ans = [];
    for (const [a, b, qC, qD] of queries) {
        const c = n - 1 - qD;
        const d = n - 1 - qC;
        const minL = Math.min(a, c);
        const maxR = Math.max(b, d);
        if (diff[minL] > 0 || (diff[m] - diff[maxR + 1]) > 0) {
            ans.push(false);
            continue;
        }
        if (Math.max(a, c) > Math.min(b, d) + 1) {
            const midL = Math.min(b, d) + 1;
            const midR = Math.max(a, c) - 1;
            if (diff[midR + 1] - diff[midL] > 0) {
                ans.push(false);
                continue;
            }
        }
        const c1 = getCnt(cnt1, a, b);
        const c2 = getCnt(cnt2, c, d);
        if (b < c || d < a) {
            const ref2 = getCnt(cnt2, a, b);
            const ref1 = getCnt(cnt1, c, d);
            let ok = true;
            for (let k = 0; k < 26; k++) {
                if (c1[k] !== ref2[k] || c2[k] !== ref1[k]) { ok = false; break; }
            }
            ans.push(ok);
        } else {
            const interL = Math.max(a, c);
            const interR = Math.min(b, d);
            let ok = true;
            const rem1 = [...c1];
            const rem2 = [...c2];
            if (a < interL) {
                const sub = getCnt(cnt2, a, interL - 1);
                for (let k = 0; k < 26; k++) {
                    rem1[k] -= sub[k];
                    if (rem1[k] < 0) ok = false;
                }
            } else if (c < interL) {
                const sub = getCnt(cnt1, c, interL - 1);
                for (let k = 0; k < 26; k++) {
                    rem2[k] -= sub[k];
                    if (rem2[k] < 0) ok = false;
                }
            }
            if (b > interR) {
                const sub = getCnt(cnt2, interR + 1, b);
                for (let k = 0; k < 26; k++) {
                    rem1[k] -= sub[k];
                    if (rem1[k] < 0) ok = false;
                }
            } else if (d > interR) {
                const sub = getCnt(cnt1, interR + 1, d);
                for (let k = 0; k < 26; k++) {
                    rem2[k] -= sub[k];
                    if (rem2[k] < 0) ok = false;
                }
            }
            if (!ok) {
                ans.push(false);
            } else {
                let match = true;
                for (let k = 0; k < 26; k++) {
                    if (rem1[k] !== rem2[k]) { match = false; break; }
                }
                ans.push(match);
            }
        }
    }
    return ans;
};
